/**
 * Parity with the reference implementation. For each committed fixture, analyze(fixture).reports[0]
 * deep-equals the reference report (scores at four decimals), and analyze on the fixture with its
 * items stripped re-derives the same items (stage 1 parity).
 *
 * The reference JSON under src/specs/parity/ is regenerated by one command per fixture and committed:
 *   python3 scripts/autopsy-check.py --fixture src/fixtures/<id>.json --report-json > src/specs/parity/<id>.report.json
 * No Python runs at test time.
 */
import { describe, expect, it } from 'vitest'
import { CLOSING_LINE, analyze, type ItemReport, type Report, type Session } from '../domain'
import { fixtures } from '../fixtures/index.ts'
import healthyRun2 from './parity/healthy-run2.report.json'
import constructedTicket from './parity/constructed-ticket.report.json'
import constructedFileEdit from './parity/constructed-file-edit.report.json'

type ReferenceReport = Omit<Report, 'closing'>

const REFERENCE: Record<string, ReferenceReport> = {
  ...(healthyRun2 as Record<string, ReferenceReport>),
  ...(constructedTicket as Record<string, ReferenceReport>),
  ...(constructedFileEdit as Record<string, ReferenceReport>),
}

const round4 = (n: number) => Math.round(n * 1e4) / 1e4

function comparable(items: ItemReport[]): ItemReport[] {
  return items.map((r) => {
    const row: ItemReport = { ...r, survival: { ...r.survival, score: round4(r.survival.score) } }
    if (r.restatement) row.restatement = { ...r.restatement, score: round4(r.restatement.score) }
    return row
  })
}

describe('parity with scripts/autopsy-check.py', () => {
  it.each(fixtures.map((s) => [s.id, s] as const))('%s: reports[0] equals the committed reference report', (id, session) => {
    const want = REFERENCE[id]
    expect(want, `reference for ${id}`).toBeDefined()
    const { reports } = analyze(session)
    expect(reports).toHaveLength(1)
    const got = reports[0]
    expect(got.closing).toBe(CLOSING_LINE)
    expect({ sessionId: got.sessionId, compactionIndex: got.compactionIndex, items: comparable(got.items) }).toEqual({
      sessionId: want.sessionId,
      compactionIndex: want.compactionIndex,
      items: comparable(want.items),
    })
  })

  it.each(fixtures.map((s) => [s.id, s] as const))('%s: items stripped, stage 1 re-derives the same items', (_id, session) => {
    const { items: _items, ...rest } = session
    const stripped: Session = rest
    const { reports } = analyze(stripped)
    expect(reports).toHaveLength(1)
    expect(reports[0].items.map((r) => r.item)).toEqual(session.items)
    // And the derived items yield the same verdicts as the pre-labeled ones.
    expect(comparable(reports[0].items)).toEqual(comparable(analyze(session).reports[0].items))
  })
})
